parameters.functionCode:
const headers = $input.first().json.headers || {};
const token   = headers['x-internal-token'] || headers['X-Internal-Token'];

if (!token || token !== $env.INTERNAL_WEBHOOK_SECRET) {
  throw new Error('UNAUTHORIZED_REQUEST: invalid or missing token');
}

return [{ json: $input.first().json }];

const lead   = $items('Load Lead + Brief + Company')[0]?.json;
const config = $items('Load Client ICP Config')[0]?.json;

if (!lead || !lead.lead_id) {
  throw new Error('SCORING_FAILED: lead not found');
}
if (!config || !config.icp_config) {
  throw new Error('SCORING_FAILED: client ICP config missing');
}

// Parse JSONB columns if returned as strings
const parseCol = (val) => {
  if (!val) return null;
  if (typeof val === 'object') return val;
  try { return JSON.parse(val); } catch(e) { return null; }
};

const brief       = parseCol(lead.brief)       || {};
const rawEnrich   = parseCol(lead.raw_enrichment) || {};
const techStack   = parseCol(lead.tech_stack)  || [];
const icpConfig   = parseCol(config.icp_config);
const weights     = parseCol(config.scoring_weights) || {
  industry:    25,
  company_size: 20,
  title_seniority: 25,
  revenue_band:    20,
  tech_stack:      10
};
const tiers       = parseCol(config.tier_thresholds) || {
  A: 75,
  B: 50,
  C: 0
};

return [{
  json: {
    lead,
    brief,
    raw_enrichment: rawEnrich,
    tech_stack: Array.isArray(techStack) ? techStack : [],
    icp_config: icpConfig,
    weights,
    tiers,
    config_id: config.config_id
  }
}];

// ── ICP Scoring Engine v2 ──────────────────────────────────────────
// Scores a lead 0-100 across 5 weighted dimensions.
// Applies 3 bonus adjustments: intent signals, founder detection,
// data completeness. Final score capped at 100.

const { lead, brief, tech_stack: rawTechStack, icp_config, weights, tiers } = $input.first().json;

const icp = icp_config || {};

// ── Fix: SQL aliases company fields — map them explicitly ─────────
// The JOIN returns c.industry AS industry, c.employee_count etc.
// They land on `lead` since they're all in the same result row.
// Alias them clearly so intent is obvious throughout.
const industry      = lead.industry      || null;   // from c.industry
const sub_industry  = lead.sub_industry  || null;   // from c.sub_industry
const employee_count = lead.employee_count || null; // from c.employee_count
const annual_revenue = lead.annual_revenue || null; // from c.annual_revenue
const title          = lead.title          || '';   // from l.title

// ── Fix: tech_stack type guard ────────────────────────────────────
// JSONB columns can occasionally arrive as strings; guard defensively.
const tech_stack = Array.isArray(rawTechStack)
  ? rawTechStack
  : (typeof rawTechStack === 'string'
      ? (() => { try { return JSON.parse(rawTechStack); } catch(e) { return []; } })()
      : []);

// ── Helper: normalise weight object to sum to 1.0 ─────────────────
function normaliseWeights(w) {
  const total = Object.values(w).reduce((a, b) => a + Number(b), 0);
  if (total === 0) return w;
  return Object.fromEntries(Object.entries(w).map(([k, v]) => [k, Number(v) / total]));
}

const W = normaliseWeights(weights);

const scoreBreakdown  = {};
const reasonBreakdown = {};

// ── 1. INDUSTRY ────────────────────────────────────────────────────
(function scoreIndustry() {
  const target    = (icp.target_industries  || []).map(s => s.toLowerCase());
  const exclude   = (icp.exclude_industries || []).map(s => s.toLowerCase());
  const actual    = (industry     || '').toLowerCase();
  const subActual = (sub_industry || '').toLowerCase();

  if (!actual) {
    scoreBreakdown.industry = 25;
    reasonBreakdown.industry = 'unknown_industry';
    return;
  }
  if (exclude.some(e => actual.includes(e))) {
    scoreBreakdown.industry = 0;
    reasonBreakdown.industry = `excluded:${actual}`;
    return;
  }
  if (target.length === 0) {
    scoreBreakdown.industry = 75;
    reasonBreakdown.industry = 'no_filter_configured';
    return;
  }
  if (target.some(t => actual.includes(t))) {
    scoreBreakdown.industry = 100;
    reasonBreakdown.industry = `matched:${actual}`;
  } else if (target.some(t => subActual.includes(t))) {
    scoreBreakdown.industry = 60;
    reasonBreakdown.industry = `sub_industry_match:${subActual}`;
  } else {
    scoreBreakdown.industry = 0;
    reasonBreakdown.industry = `no_match:${actual}`;
  }
})();

// ── 2. COMPANY SIZE ────────────────────────────────────────────────
(function scoreCompanySize() {
  const targetBands = icp.target_employee_bands || [];
  const count = parseInt(employee_count, 10);

  if (isNaN(count)) {
    scoreBreakdown.company_size = 30;
    reasonBreakdown.company_size = 'unknown_employee_count';
    return;
  }
  if (targetBands.length === 0) {
    if      (count >= 50   && count <= 200)  scoreBreakdown.company_size = 100;
    else if (count >= 201  && count <= 1000) scoreBreakdown.company_size = 85;
    else if (count >= 1001 && count <= 5000) scoreBreakdown.company_size = 60;
    else if (count >= 10   && count < 50)    scoreBreakdown.company_size = 50;
    else if (count > 5000)                   scoreBreakdown.company_size = 30;
    else                                     scoreBreakdown.company_size = 10;
    reasonBreakdown.company_size = `default_band:${count}`;
    return;
  }
  let best = 0;
  for (const band of targetBands) {
    if (count >= band.min && count <= band.max) best = Math.max(best, band.score || 100);
  }
  scoreBreakdown.company_size = best;
  reasonBreakdown.company_size = `config_band:${count}`;
})();

// ── 3. TITLE SENIORITY ─────────────────────────────────────────────
(function scoreSeniority() {
  const titleLow  = title.toLowerCase();
  const seniority = (
    $input.first().json.raw_enrichment?.clearbit?.seniority || ''
  ).toLowerCase();

  const targetSeniority = (icp.target_seniority || []).map(s => s.toLowerCase());

  // ── Upgrade 2: Founder detection ──────────────────────────────────
  // Founders at startups often use non-standard titles.
  // Detect them early and give full c_suite score before further logic.
  if (/founder|co-founder|cofounder|owner/i.test(titleLow)) {
    scoreBreakdown.title_seniority = 100;
    reasonBreakdown.title_seniority = 'founder_detected';
    return;
  }

  const C_SUITE    = ['ceo','cto','coo','cfo','cmo','chief','president'];
  const VP_LEVEL   = ['vp','vice president','head of','director'];
  const MANAGER    = ['manager','lead','principal','senior','staff'];
  const INDIVIDUAL = ['engineer','analyst','developer','associate','specialist','coordinator'];

  let detectedTier = 'unknown';
  if      (C_SUITE.some(k    => titleLow.includes(k) || seniority.includes(k))) detectedTier = 'c_suite';
  else if (VP_LEVEL.some(k   => titleLow.includes(k) || seniority.includes(k))) detectedTier = 'vp';
  else if (MANAGER.some(k    => titleLow.includes(k) || seniority.includes(k))) detectedTier = 'manager';
  else if (INDIVIDUAL.some(k => titleLow.includes(k)))                          detectedTier = 'individual';

  const SENIORITY_SCORES = { c_suite: 100, vp: 85, manager: 65, individual: 25, unknown: 30 };

  if (targetSeniority.length === 0) {
    scoreBreakdown.title_seniority = SENIORITY_SCORES[detectedTier];
    reasonBreakdown.title_seniority = `default:${detectedTier}`;
    return;
  }
  if (targetSeniority.includes(detectedTier)) {
    scoreBreakdown.title_seniority = 100;
    reasonBreakdown.title_seniority = `target_match:${detectedTier}`;
  } else {
    const ORDER = ['c_suite','vp','manager','individual'];
    const targetIdx   = Math.min(...targetSeniority.map(t => ORDER.indexOf(t)).filter(i => i >= 0));
    const detectedIdx = ORDER.indexOf(detectedTier);
    const gap = Math.abs(targetIdx - detectedIdx);
    scoreBreakdown.title_seniority = gap === 1 ? 50 : gap === 2 ? 20 : 0;
    reasonBreakdown.title_seniority = `gap_${gap}:${detectedTier}_vs_${targetSeniority.join('|')}`;
  }
})();

// ── 4. REVENUE BAND ────────────────────────────────────────────────
(function scoreRevenue() {
  const targetBands = icp.target_revenue_bands || [];
  const revenue = typeof annual_revenue === 'number'
    ? annual_revenue
    : parseInt(String(annual_revenue || '0').replace(/[^0-9]/g, ''), 10);

  if (!revenue || isNaN(revenue)) {
    scoreBreakdown.revenue_band = 30;
    reasonBreakdown.revenue_band = 'unknown_revenue';
    return;
  }
  if (targetBands.length === 0) {
    if      (revenue >= 1e6  && revenue <= 1e7)  scoreBreakdown.revenue_band = 100;
    else if (revenue >= 1e7  && revenue <= 5e7)  scoreBreakdown.revenue_band = 85;
    else if (revenue >= 5e7  && revenue <= 2e8)  scoreBreakdown.revenue_band = 65;
    else if (revenue >= 1e5  && revenue < 1e6)   scoreBreakdown.revenue_band = 40;
    else if (revenue > 2e8)                       scoreBreakdown.revenue_band = 30;
    else                                          scoreBreakdown.revenue_band = 10;
    reasonBreakdown.revenue_band = `default_band:${revenue}`;
    return;
  }
  let best = 0;
  for (const band of targetBands) {
    if (revenue >= band.min && revenue <= band.max) best = Math.max(best, band.score || 100);
  }
  scoreBreakdown.revenue_band = best;
  reasonBreakdown.revenue_band = `config_band:${revenue}`;
})();

// ── 5. TECH STACK SIGNALS ──────────────────────────────────────────
(function scoreTechStack() {
  const targetTech  = (icp.target_technologies  || []).map(t => t.toLowerCase());
  const bonusTech   = (icp.bonus_technologies   || []).map(t => t.toLowerCase());
  const excludeTech = (icp.exclude_technologies || []).map(t => t.toLowerCase());

  // ── Fix: type guard applied before .map() ─────────────────────────
  const stack = Array.isArray(tech_stack)
    ? tech_stack.map(t => String(t).toLowerCase())
    : [];

  if (targetTech.length === 0 && bonusTech.length === 0) {
    scoreBreakdown.tech_stack = 50;
    reasonBreakdown.tech_stack = 'no_tech_filter';
    return;
  }
  if (excludeTech.some(ex => stack.includes(ex))) {
    scoreBreakdown.tech_stack = 0;
    reasonBreakdown.tech_stack = 'excluded_tech_detected';
    return;
  }
  const matched    = targetTech.filter(t => stack.some(s => s.includes(t)));
  const bonus      = bonusTech.filter(t  => stack.some(s => s.includes(t)));
  const matchRatio = targetTech.length > 0 ? matched.length / targetTech.length : 1;
  const baseScore  = Math.round(matchRatio * 80);
  const bonusScore = Math.min(bonus.length * 10, 20);
  scoreBreakdown.tech_stack = Math.min(baseScore + bonusScore, 100);
  reasonBreakdown.tech_stack = `matched:${matched.join(',') || 'none'}|bonus:${bonus.join(',') || 'none'}`;
})();

// ── Weighted base score ────────────────────────────────────────────
let finalScore = Math.round(
  (scoreBreakdown.industry        || 0) * W.industry +
  (scoreBreakdown.company_size    || 0) * W.company_size +
  (scoreBreakdown.title_seniority || 0) * W.title_seniority +
  (scoreBreakdown.revenue_band    || 0) * W.revenue_band +
  (scoreBreakdown.tech_stack      || 0) * W.tech_stack
);

// ── ICP signals and flags from AI brief ───────────────────────────
const icpSignals = brief.icp_signals || [];
const riskFlags  = brief.risk_flags  || [];
const painPoints = brief.pain_points || [];

// ── Upgrade 1: AI intent signal boost (+5, max once) ──────────────
// Buying signals detected in the AI brief lift the score.
// Signals: hiring, expanding, recent funding, scaling, switching tools.
const INTENT_PATTERN = /hiring|expanding|funding|scaling|switching|growing|launched|raised/i;
const hasIntentSignal = icpSignals.some(s => INTENT_PATTERN.test(s))
                     || (brief.company_summary || '').match(INTENT_PATTERN);
if (hasIntentSignal) {
  finalScore += 5;
  reasonBreakdown.intent_boost = 'intent_signal_detected';
}

// ── Upgrade 3: Data completeness bonus (+5, max once) ─────────────
// Reward leads where enrichment returned high-quality coverage.
// Each present field = 1 point; 3/3 triggers the bonus.
let completeness = 0;
if (employee_count && !isNaN(parseInt(employee_count, 10))) completeness += 1;
if (annual_revenue && annual_revenue !== '0')                completeness += 1;
if (tech_stack.length > 0)                                   completeness += 1;
if (completeness >= 3) {
  finalScore += 5;
  reasonBreakdown.completeness_bonus = `all_3_fields_present`;
}

// ── Hard cap at 100 ───────────────────────────────────────────────
finalScore = Math.min(finalScore, 100);

// ── Tier assignment ────────────────────────────────────────────────
let tier = 'C';
if      (finalScore >= tiers.A) tier = 'A';
else if (finalScore >= tiers.B) tier = 'B';

// ── Risk penalty: hard flags from AI brief (−15) ──────────────────
// Re-evaluated after bonuses so a genuinely risky lead can't be
// boosted into Tier A by intent signals alone.
const hasHardRisk = riskFlags.some(r =>
  /budget|competitor|churned|bankrupt|acquired|shutdown|do not contact/i.test(r)
);
let adjustedScore = hasHardRisk ? Math.max(finalScore - 15, 0) : finalScore;

if (hasHardRisk) {
  if      (adjustedScore >= tiers.A) tier = 'A';
  else if (adjustedScore >= tiers.B) tier = 'B';
  else                               tier = 'C';
  reasonBreakdown.risk_penalty = 'hard_risk_flag_detected(-15)';
}

return [{
  json: {
    lead_id:          $input.first().json.lead.lead_id,
    company_id:       $input.first().json.lead.company_id,
    config_id:        $input.first().json.config_id,
    score:            adjustedScore,
    raw_score:        finalScore,
    tier,
    score_breakdown:  scoreBreakdown,
    reason_breakdown: reasonBreakdown,
    weights_used:     W,
    icp_signals:      icpSignals,
    risk_flags:       riskFlags,
    pain_points:      painPoints,
    has_hard_risk:    hasHardRisk,
    has_intent_signal: !!hasIntentSignal,
    data_completeness: completeness,
    scored_at:        new Date().toISOString(),
    execution_id:     $execution.id
  }
}];

