const err = $input.first().error || {};
const msg = err.message || 'Unknown error in WF-03';

const isAuth    = msg.includes('UNAUTHORIZED_REQUEST');
const isFailed  = msg.includes('SCORING_FAILED');

return [{
  json: {
    status:       isAuth ? 'unauthorized' : isFailed ? 'scoring_failed' : 'error',
    message:      msg,
    workflow:     'WF-03',
    timestamp:    new Date().toISOString(),
    execution_id: $execution.id
  }
}];
